node -e "
const fs = require('fs');

// Check the xlsx file
try {
  const data = fs.readFileSync('/workspace/testbed/data/product_inventory.xlsx');
  console.log('product_inventory.xlsx size:', data.length);
} catch(e) { console.log(e.message); }

// Check the db file
try {
  const data = fs.readFileSync('/workspace/world.db');
  // Look for 'crew' or 'tee' in the binary
  const str = data.toString('utf8', 0, data.length);
  const idx = str.toLowerCase().indexOf('crew tee');
  if (idx >= 0) {
    console.log('Found crew tee in world.db at offset', idx);
    console.log('Context:', str.substring(Math.max(0,idx-100), idx+100));
  } else {
    console.log('No crew tee in world.db');
  }
} catch(e) { console.log(e.message); }
"

node -e "
const db = require('better-sqlite3')('/workspace/world.db');

// List tables
const tables = db.prepare(\"SELECT name FROM sqlite_master WHERE type='table'\").all();
console.log('Tables:', tables.map(t => t.name));

// Check for crew tee related tables
for (const t of tables) {
  const cols = db.prepare('PRAGMA table_info(' + t.name + ')').all();
  console.log('\n' + t.name + ':', cols.map(c => c.name).join(', '));

  // Check row count
  const count = db.prepare('SELECT count(*) as cnt FROM ' + t.name).get();
  console.log('  Rows:', count.cnt);
}
"

node -e "
const db = require('better-sqlite3')('/workspace/world.db');

// Search for Crew Tee products
const products = db.prepare(\"SELECT * FROM products WHERE name LIKE '%Crew Tee%'\").all();
console.log('=== Products matching Crew Tee ===');
for (const p of products) {
  console.log(JSON.stringify(p, null, 2));
  console.log('---');
}

// Also check for 'Everyday' in product names
const everyday = db.prepare(\"SELECT * FROM products WHERE name LIKE '%Everyday%'\").all();
console.log('\n=== Products matching Everyday ===');
for (const p of everyday) {
  console.log(JSON.stringify(p, null, 2));
  console.log('---');
}
"

node -e "
const db = require('better-sqlite3')('/workspace/world.db');

// Check variants for the Everyday Crew Tee
const variants = db.prepare(\"SELECT * FROM rt_variants WHERE product_id = '2460285426'\").all();
console.log('=== Variants for Everyday Crew Tee (2460285426) ===');
for (const v of variants) { console.log(JSON.stringify(v)); }

// Check order items
const oi = db.prepare(\"SELECT * FROM order_items WHERE name LIKE '%Crew Tee%' OR product_id = '2460285426'\").all();
console.log('\n=== Order items for Crew Tee ===');
for (const o of oi) { console.log(JSON.stringify(o)); }

// Check cart items
const ci = db.prepare(\"SELECT * FROM cart_items WHERE product_id = '2460285426'\").all();
console.log('\n=== Cart items ===');
for (const c of ci) { console.log(JSON.stringify(c)); }

// Also check Harbor Cotton Crew Tee variants
const variants2 = db.prepare(\"SELECT * FROM rt_variants WHERE product_id = 'PROD-F9994E'\").all();
console.log('\n=== Variants for Harbor Cotton Crew Tee (PROD-F9994E) ===');
for (const v of variants2) { console.log(JSON.stringify(v)); }
"

